/**
 * Refresh the channel inventory in `ipc-channels.test.ts`.
 *
 * The file says "auto-generated by scripts/ipc-inventory.ts", but that script is not in the tree —
 * so the list drifted: the office channels landed without it. This rebuilds the array (and the
 * count, which is derived from it) from `RPC_CHANNELS` itself, which is the only truth.
 *
 *   bun scripts/refresh-channel-inventory.ts
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { RPC_CHANNELS } from '../apps/electron/src/shared/types'

const FILE = resolve(import.meta.dir, '..', 'apps', 'electron', 'src', 'shared', '__tests__', 'ipc-channels.test.ts')

function flatten(obj: Record<string, unknown>): string[] {
  return Object.values(obj).flatMap((value) =>
    typeof value === 'string'
      ? [value]
      : value && typeof value === 'object'
        ? flatten(value as Record<string, unknown>)
        : [],
  )
}

const channels = flatten(RPC_CHANNELS as unknown as Record<string, unknown>).sort()
const block = [
  '// Auto-generated by scripts/refresh-channel-inventory.ts — DO NOT edit by hand.',
  `const EXPECTED_CHANNELS: string[] = [`,
  ...channels.map((channel) => `  '${channel}',`),
  `]`,
  `const EXPECTED_COUNT = EXPECTED_CHANNELS.length`,
].join('\n')

const source = readFileSync(FILE, 'utf8')
const start = Math.max(
  source.indexOf('// Auto-generated by scripts/ipc-inventory.ts'),
  source.indexOf('// Auto-generated by scripts/refresh-channel-inventory.ts'),
)
const end = source.indexOf('// End auto-generated')
if (start === -1 || end === -1) {
  console.error('No auto-generated block found — refusing to guess where to write.')
  process.exit(1)
}

const next = source.slice(0, start) + block + '\n' + source.slice(end)
writeFileSync(FILE, next, 'utf8')
console.log(`Wrote ${channels.length} channels to ${join('apps', 'electron', 'src', 'shared', '__tests__', 'ipc-channels.test.ts')}`)
